import { expect, test } from '@playwright/test';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { collectConsoleErrors, resetBackend, showAllControls, uploadAndWaitReady } from './helpers';

const here = path.dirname(fileURLToPath(import.meta.url));
const SEESTAR_FITS = path.join(here, 'fixtures', 'seestar-like.fits');
// A SYNTHETIC solved linear RGB FITS generated by scripts\e2e.ps1 (as in color.spec.ts).
const COLOR_DIR = process.env.EAE_COLOR_DIR;
const BAYER_FITS = path.join(here, 'fixtures', 'bayer.fits');

// A SYNTHETIC Seestar MyWorks folder: one target with a telescope stack and two raw sub-frames (copies of fixtures).
function makeMyWorks(): string {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'eae-myworks-'));
  const target = path.join(root, 'M 31');
  const subs = path.join(root, 'M 31_sub');
  fs.mkdirSync(target);
  fs.mkdirSync(subs);
  fs.copyFileSync(SEESTAR_FITS, path.join(target, 'Stacked_12_M 31_10.0s_IRCUT_20251020-221500.fit'));
  for (const n of ['00', '01']) fs.copyFileSync(BAYER_FITS, path.join(subs, `Light_M 31_10.0s_IRCUT_20251020-2215${n}.fit`));
  return root;
}

test.describe('higher-end tools: reference data, AI sharpening, star colour, annotations, Seestar import', () => {
  test.beforeEach(async ({ request }) => {
    await resetBackend(request);
  });

  test('Settings lists the optional catalogs with their credits', async ({ page }) => {
    await page.goto('/');
    await uploadAndWaitReady(page);
    await page.getByTestId('settings-button').click();
    const section = page.getByTestId('reference-data-section');
    await expect(section).toContainText('Star catalog (Gaia DR3)');
    await expect(section).toContainText('OpenNGC');
    await expect(section).toContainText('CC BY-SA 4.0');
    await expect(page.getByTestId('reference-download-objects')).toBeVisible();
  });

  test('AI sharpening, star size and accurate star colours are opt-in controls', async ({ page }) => {
    test.skip(!COLOR_DIR, 'EAE_COLOR_DIR not set (run through scripts\\e2e.ps1)');
    const errors = collectConsoleErrors(page);
    await showAllControls(page);
    await page.goto('/');
    await page.getByTestId('file-input').setInputFiles(path.join(COLOR_DIR as string, 'solved-rgb.fits'));
    await page.getByTestId('intake-option-linear').click();
    await expect(page.getByTestId('asset-status')).toHaveText('Ready');
    await expect(page.getByTestId('switch-ai-sharpen')).not.toBeChecked();
    await page.getByTestId('switch-ai-sharpen').check({ force: true });
    await expect(page.locator('#ai-sharpen-amount')).toHaveValue('50');
    await expect(page.getByTestId('ai-state-sharpen')).toContainText(/Download|Ready|not installed/);
    await page.getByTestId('switch-ai-stars').check({ force: true });
    await expect(page.locator('#ai-star-size')).toHaveValue('100');
    await page.getByText('Star colour', { exact: true }).click();
    const accurate = page.getByTestId('switch-catalog-builtin');
    await expect(accurate).not.toBeChecked();
    const sky = page.getByTestId('star-colour-tools').getByTestId('sky-solution');
    await expect(sky).toContainText('Sky position');
    await expect(sky).toContainText('Reference data');  // no star catalog in the test data folder
    await accurate.check({ force: true });
    await expect(page.getByTestId('preset-select')).toHaveValue('auto');  // opt-in tools are not part of the look: Auto stays
    await page.getByTestId('panel-simple').click();
    await expect(page.getByTestId('simple-note')).toContainText('AI sharpening');
    await expect(page.getByTestId('simple-note')).toContainText('accurate star colours');
    expect(errors).toEqual([]);
  });

  test('Edit export explains what annotations need when the star catalog is missing', async ({ page }) => {
    await page.goto('/');
    await uploadAndWaitReady(page);
    await page.getByTestId('enhance-selected').click();
    await expect(page.getByTestId('asset-status').first()).toHaveText(/^Complete/, { timeout: 60_000 });
    await page.getByRole('button', { name: 'Edit export…' }).click();
    const box = page.getByTestId('annotations');
    // No star catalog in the test data folder, so the dialog can't find the sky position by itself: it says what to download.
    await expect(box).toContainText('Annotations need the star catalog');
    await expect(page.getByTestId('annotate-objects')).toBeDisabled();
    await expect(page.getByTestId('annotate-compass')).toBeDisabled();

    // In a short window the dialog scrolls; the preview keeps its own space and never runs under the controls.
    await page.setViewportSize({ width: 1040, height: 640 });
    await page.getByRole('button', { name: 'Rotate left 90°' }).click();
    const img = page.getByRole('img', { name: 'Edited export preview' });
    await expect(img).toBeVisible();
    await expect.poll(async () => {
      const a = await page.locator('.edit-export-preview').boundingBox();
      const i = await img.boundingBox();
      const b = await page.getByRole('button', { name: 'Rotate left 90°' }).boundingBox();
      return a && i && b ? Math.round(Math.max(i.y + i.height - (a.y + a.height), i.y + i.height - b.y)) : 999;
    }).toBeLessThanOrEqual(0);
  });

  test('Import from Seestar lists targets and adds the newest stack in one click', async ({ page }) => {
    const errors = collectConsoleErrors(page);
    const root = makeMyWorks();
    await page.goto('/');
    await page.getByTestId('seestar-button-empty').click();
    await expect(page.getByTestId('seestar-dialog')).toBeVisible();
    await page.getByTestId('seestar-path').fill(root);  // typed paths are kept even if the automatic first look finishes later
    await page.getByTestId('seestar-scan').click();
    const target = page.getByTestId('seestar-target');
    await expect(target).toHaveCount(1);
    await expect(target).toContainText('M 31');
    await expect(target).toContainText('12 frames');
    await expect(target).toContainText('2 sub-frames saved');
    await page.getByTestId('seestar-add-stack').click();
    await expect(page.getByTestId('seestar-dialog')).toBeHidden();
    const card = page.getByTestId('asset-card').first();
    await expect(card).toContainText('Stacked_12');
    // An added FITS asks the usual intake questions; the Seestar header makes the answers recommended.
    const intake = page.getByTestId('intake-dialog');
    await expect(intake.getByTestId('intake-recommendation')).toContainText('Seestar', { timeout: 30_000 });
    await intake.getByTestId('intake-option-layout-rgb_planes').click();
    await page.getByTestId('intake-option-linear').click();
    await expect(card.getByTestId('asset-status')).toHaveText('Ready', { timeout: 60_000 });
    expect(fs.readdirSync(path.join(root, 'M 31'))).toEqual(['Stacked_12_M 31_10.0s_IRCUT_20251020-221500.fit']);  // read-only

    // The folder is remembered; Stack sub-frames opens the stack dialog already scanned, with automatic enhancement on.
    await page.getByTestId('seestar-button').click();
    await expect(page.getByTestId('seestar-path')).toHaveValue(root);
    await page.getByTestId('seestar-stack-subs').click();
    await expect(page.getByTestId('stack-dialog')).toBeVisible();
    await expect(page.getByTestId('stack-folder')).toHaveValue(path.join(root, 'M 31_sub'));
    await expect(page.getByTestId('stack-summary')).toContainText('2 sub-frames');
    await expect(page.getByTestId('stack-auto-enhance')).toBeChecked();
    expect(errors).toEqual([]);
  });
});
